{
  "aggregate_id": "DEF-LVMC-11-02-083::electric_scooter",
  "classifications": [
    {
      "class": "ru.electric_scooter",
      "verdict": "underdetermined",
      "reason": "The contract supplies handlebars and standing or seated electric operation but does not establish the mandatory weight and motor-only maximum-speed limits."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "An assisting electric motor is compatible with the admitting words, but the contract does not settle the required weight and motor-only maximum speed."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "A low-power two- or three-wheeler can match the electric-device description, but its contract does not settle the required motor type, weight, or maximum speed."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The motorcycle contract neither rules out a qualifying electric model nor establishes the required electric motor, handlebars, weight, and maximum speed."
    },
    {
      "class": "ru.bicycle",
      "verdict": "underdetermined",
      "reason": "Human propulsion does not establish the absence of an electric motor, and the admitting words expressly permit propulsion provided by the rider."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian and expressly does not stand in for a scooter rider, whereas the admitting words describe a ride-on electric device."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a visibly young pedestrian, not the ride-on electric device described by the admitting words."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian with specified assistance, not the ride-on electric device described by the admitting words."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract does not make every self-propelled non-rail vehicle incompatible with handlebars or the weight limit, and its separately classified two-wheeler restriction does not establish exclusion of every possible qualifying device."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "The many-passenger design requirement establishes neither incompatible steering nor a weight exceeding one hundred pounds."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "The school-passenger designation and required markings establish neither incompatibility with handlebars nor a weight exceeding one hundred pounds."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public transit service and identifying livery or route displays do not establish that every contract member fails the quoted device or weight requirements."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "Neither the tour-or-shuttle branch nor the lengthened hire-vehicle branch specifies steering or weight restrictions that rule out every qualifying device."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "The passenger-for-hire and markings requirements do not establish incompatibility with the quoted device characteristics or weight limit."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "The commercially licensed branch does not require any minimum weight, so the quoted weight limit cannot exclude the entire class."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A goods-carrying body does not, under the posted contract, establish either incompatible steering or a weight exceeding one hundred pounds."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "The quoted propulsion and weight requirements do not rule out every powered combination allowed by the contract."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "Being on-track equipment does not establish incompatibility with handlebars, electric propulsion, or the quoted weight limit."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "underdetermined",
      "reason": "Jurisdictional emergency designation imposes no contract requirement incompatible with the quoted device characteristics or weight limit."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The fire-fighting function does not establish that every contract member lacks the required device characteristics or exceeds the weight limit."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "underdetermined",
      "reason": "Official or contracted road service and identifying livery or equipment do not establish incompatibility with the quoted device characteristics or weight limit."
    }
  ]
}

